import type { FilterValue } from 'models/Filters';
import {
  isCanonicalMonthStartDate,
  parseDtEndToTimePeriodEnd,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

/**
 * Resolves the canonical period type used by big-numbers cards and chart requests.
 * QTR tray selections are anchored to the selected quarter card (Q1-Q4).
 */
export function getVolumeBigNumbersCardPeriodType(
  chartPeriodType: string | null | undefined,
  dtEnd: FilterValue | undefined,
): string | null {
  if (!chartPeriodType) return null;

  const normalized = String(chartPeriodType).trim().toUpperCase();

  if (normalized === TimePeriodType.QTR && isCanonicalMonthStartDate(dtEnd)) {
    const quarter = parseDtEndToTimePeriodEnd(TimePeriodType.QTR, dtEnd);
    return quarter ?? normalized;
  }

  return normalized;
}
